Response:
{% comment %} From is E.164: +1 and then the area code, for North American numbers. {% endcomment %}
{% assign country = From | slice: 0, 2 %}
{% assign area = From | slice: 2, 3 %}
{% if country != "+1" %}{% assign area = "" %}{% endif %}

{% comment %} A key pressed in the menu below takes priority over the area code. {% endcomment %}
{% case Digits %}
  {% when "1" %}{% assign area = "505" %}
  {% when "2" %}{% assign area = "602" %}
  {% when "3" %}{% assign area = "915" %}
{% endcase %}

{% case area %}
  {% when "505", "575" %}
    {% assign store = "Albuquerque" %}
    {% assign line = "+15055550101" %}
  {% when "480", "520", "602", "623", "928" %}
    {% assign store = "Phoenix" %}
    {% assign line = "+16025550101" %}
  {% when "915" %}
    {% assign store = "El Paso" %}
    {% assign line = "+19155550101" %}
{% endcase %}

{% if store %}
  Thank you for calling Los Pollos Hermanos, the chicken brothers. Connecting you to our {{ store }} restaurant.

    {{ line }}

  Thank you for calling Los Pollos Hermanos. Goodbye.


{% else %}


    Thank you for calling Los Pollos Hermanos, the chicken brothers.
    For Albuquerque, press 1. For Phoenix, press 2. For El Paso, press 3.

  We did not receive a selection. Goodbye.

{% endif %}
